    "sourceHash": "sha256:93bbcf0a18ea92b556a43c9a080cd664426743c0c5980dc9a173990742e7f955",
    "translatableHash": "sha256:544411d1fdab97afd1859e19b489df2b820dfd29628db4cf401d7cd78d195d7f",
    "data": {
      "schemaVersion": 1,
      "name": "Putrid Sack of Rotting Fruit",
      "itemType": "consumable",
      "level": 3,
      "rarity": "uncommon",
      "traits": [
        "consumable"
      ],
      "description": "Activate 1 Strike\nEach of these unassuming sacks contains enough rotting fruit to provide a fungus leshy with 1 week's worth of rations, along with clusters of stones to help press out the fruit's juices. Since their last adventure, Reaching Rings has refined their rations's ability to serve as a weapon in addition to delicious, flavorful sustenance.\nA sack of rotting fruit has a range increment of 20 feet. When you succeed at a ranged Strike on a creature by hurling a putrid sack of rotten fruit at them, the sack is consumed while the creature takes 2d6 bludgeoning damage and must attempt a check (fortitude, dc:17) save.\nSuccess The creature is unaffected by the foul smell of the fruit.\nFailure The creature becomes Sickened 1.\nCritical Failure The creature becomes Sickened 2.",
      "bulk": 0.1,
      "price": {
        "gp": 12
      },
      "usage": "held-in-one-hand",
      "category": "other",
      "group": "consumable"
    }
