    "sourceHash": "sha256:971b8f6e2a216cd704115b1d46e9076332062c0cf8546699aa907c136a1bcb7b",
    "translatableHash": "sha256:6eb1e3917c37da6229adb2433ae9b538d5d640500364e6814410a3f1faa0aa23",
    "data": {
      "schemaVersion": 1,
      "name": "Secret-Keeper's Mask (Reaper of Reputation)",
      "itemType": "equipment",
      "level": 3,
      "rarity": "rare",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "Each of these full-face masks is made of stitched materials—often including humanoid skin—and has a single, bulbous eye. While wearing the mask, you gain a +1 item bonus to Deception checks to Lie and the mask doesn't impair your vision. The mask can also be activated, with an ability based on its type.\nThis mask is made of gray and black tiles sewn together. It has a messy, inky spiral over the mouth.\nActivate 1 Interact (auditory, linguistic)\nFrequency once per day\nEffect You touch the mask's spiral and identify a target creature within 30 feet. For the next 10 minutes, any normal speech you utter can, at your discretion, be inaudible to all creatures except the target creature, who can hear you clearly regardless of ambient sound so long as it is within 1 mile. This ability doesn't silence magical words, such as the verbal component of spellcasting or commands to activate magic items.",
      "bulk": 0,
      "price": {
        "gp": 60
      },
      "usage": "wornmask",
      "category": "equipment",
      "group": "equipment"
    }
